#ifdef NONMATCHING
static f32 angleABf(f32 x1, f32 y1, f32 x2, f32 y2) {
	f32 xdiff, ydiff;
	f32 xabs, yabs;
	f32 v8;
	f32 v9;
	int v10;
	f32 v13;
	f32 v15;
	f32 test;

	xdiff = x2 - x1;
	ydiff = y2 - y1;
	xabs = __fabsf(xdiff);
	yabs = __fabsf(ydiff);
	if (xabs > yabs) {
		v8 = 45.0f * (yabs / xabs);
		v9 = 2.0f * v8;
		if (v9 >= 0.0f) {
			v10 = (int)(0.5 + v9);
		}
		else {
			v10 = -(int)(0.5 - v9);
		}
		test = v8 * angleABTBL[v10];
		if (xdiff >= 0.0f) {
			if (ydiff >= 0.0f) {
				v13 = 90.0f + test;
			}
			else {
				v13 = 90.0f - test;
			}
		}
		else {
			if (ydiff >= 0.0f) {
				v13 = 270.0f - test;
			}
			else {
				v13 = 270.0f + test;
			}
		}
	}
	else {
		if (yabs == 0.0f) {
			return 0.0f;
		}
		else {
			v15 = 45.0f * (xabs / yabs);
			v9 = 2.0f * v15;
			if (v9 >= 0.0f) {
				v10 = (int)(0.5 + v9);
			}
			else {
				v10 = -(int)(0.5 - v9);
			}
			test = v15 * angleABTBL[v10];
			if (ydiff >= 0.0f) {
				if (xdiff >= 0.0f) {
					v13 = 180.0f - test;
				}
				else {
					v13 = 180.0f + test;
				}
			}
			else {
				if (xdiff >= 0.0f) {
					v13 = 0.0f + test;
				}
				else {
					v13 = 360.0f - test;
				}
			}
		}
	}
	return v13;
}
#endif

extern int __float_nan[];
static inline s32 ps_fpclassifyf(f32 x) { switch (*(s32*)&x & 0x7F800000) { case 0x7F800000: if (*(s32*)&x & 0x007FFFFF) { return 1; } else { return 2; } break; case 0: if (*(s32*)&x & 0x007FFFFF) { return 5; } else { return 3; } break; default: return 4; } }
static inline f32 ps_sqrtf(f32 x) { if (x > 0.0f) { f64 guess = __frsqrte(x); guess = 0.5 * guess * (3.0 - guess * guess * x); guess = 0.5 * guess * (3.0 - guess * guess * x); guess = 0.5 * guess * (3.0 - guess * guess * x); return x * guess; } else if (x < 0.0) { return *(f32*)__float_nan; } else if (ps_fpclassifyf(x) == 1) { return *(f32*)__float_nan; } return x; }

//calc3D, returns the first bit of SND_3DINFO (vol, pan, span, unused)
#ifdef NONMATCHING
u32 calc3D(s32 id, Vec* pos, u8 vol, u16 dist) {
	static u8 PAN[4];
	Vec v = *pos;
	f32 d;
	f32 pd, ang;
	s16 span, pan, t;
	PaperSoundWork* wp = &psnd;

	if (id & 0x1000000) {
		v.x += wp->position.x;
		v.y += wp->position.y;
		v.z += wp->position.z;
	}
	if (id & 0x2000000) {
		v = wp->position;
	}
	pd = psnd.direction;
	ang = angleABf(wp->position.x, wp->position.z, v.x, ((Vec*)&v)->z);
	if (__fabsf(ang - pd) >= 180.0f) {
		if (ang < pd) {
			ang += 360.0f;
		}
		else {
			ang -= 360.0f;
		}
	}
	ang = (ang - pd) / 180.0f;
	t = 127.0f * ang + 127.0f;
	if (t < 64) {
		t = 127 - t;
	}
	else if (t > 196) {
		t = 196 - (t - 196);
	}
	t = t - 64;
	if (t < 0) t = 0;
	if (t > 127) t = 127;
	span = t;

	{
		f32 dx = v.x - wp->position.x; f32 dy = v.y - wp->position.y; f32 dz = v.z - wp->position.z;
		d = dx * dx + dy * dy + dz * dz;
		if (d > 0.0f) {
			f64 guess = __frsqrte(d);
			guess = 0.5 * guess * (3.0 - guess * guess * d);
			guess = 0.5 * guess * (3.0 - guess * guess * d);
			guess = 0.5 * guess * (3.0 - guess * guess * d);
			d = d * guess;
		} else if (d < 0.0) {
			d = *(f32*)__float_nan;
		} else if (ps_fpclassifyf(d) == 1) {
			d = *(f32*)__float_nan;
		}
	}
	{
		f32 c = d * (f32)cos((f32)(3.14 * ang));
		f32 ac = __fabsf(c);
		f32 q;
		if (ac > 2048.0f) ac = 2048.0f;
		q = 64.0f * ac / 2048.0f;
		if (__fabsf(ang) < 0.5f) {
			t = 64.0f - q;
			if (t < 1) t = 1;
		}
		else {
			t = 64.0f + q;
			if (t > 127) t = 127;
		}
	}
	if (t <= 64) {
		f32 sn = sin(6.2831855f * ((64 - t) * 90 / 64) / 360.0f);
		pan = 64.0f - 64.0f * sn;
	}
	else {
		f32 sn = sin(6.2831855f * ((t - 64) * 90 / 64) / 360.0f);
		pan = 64.0f + 64.0f * sn;
	}
	if (pan < 0) pan = 0;
	if (pan > 127) pan = 127;

	if (dist != 0) {
		s32 mx = dist * 100;
		f32 dd = d - 200.0f;
		if (dd > mx) dd = mx;
		if (dd < 0.0f) dd = 0.0f;
		PAN[0] = (127.0f * (mx - dd) / mx * vol) / 127.0f;
	}
	else {
		PAN[0] = vol;
	}
	if (PAN[0] > 127) PAN[0] = 127;
	PAN[1] = span;
	PAN[2] = pan;
	return *(u32*)PAN;
}
#endif

#ifdef NONMATCHING
s32 searchPSSFXList(const char* name) {
	SoundEffectEntry* entry = pssfxlist;
	int i;

	if ((s32)name >= 0) { //address, return
		return (s32)name;
	}
	for (i = 0; i < 4242; i++) {
		if (!strcmp(entry->name, name)) {
			break;
		}
		entry++;
	}
	if (i >= 4242) {
		i = 0;
	}
	return i;
}
#endif

