#ifdef NONMATCHING
BOOL psndPushGroup(void) {
	static u8 tbl[4];
	static s32 group;

	if (_psndPushGroup_trg) {
		return TRUE;
	}
	if (group > 11) {
		init_f = TRUE;
		SoundLoadDVD2Free();
		return FALSE;
	}
	_psndPushGroup_trg = TRUE;
	tbl[0] = group;
	tbl[1] = 0xFF;
	SoundLoadDVD2PushGroup(tbl);
	_psndPushGroup_trg = FALSE;
	group++;
	return TRUE;
}
#endif

